options.css:
* { box-sizing:border-box; margin:0; }
.board { background:var(--bg); color:var(--fg); font-family:var(--font);
         padding:var(--sp1); height:100%; display:flex; flex-direction:column;
         gap:var(--sp1); }
.plan { flex:1 1 auto; min-height:0; position:relative; }
.plan svg { position:absolute; inset:0; width:100%; height:100%; display:block; }

/* every machine is a hit area for the same detail modal the Andon board uses */
.station { cursor:pointer; }
.station .body { transition:none; }
.station:hover .body { filter:brightness(1.35); }
.station:hover .hit { stroke:var(--fg-dim); }

text { font-family:var(--font); }
.t-st   { font-size:9px; letter-spacing:.08em; text-transform:uppercase; }
.t-mach { font-size:9px; }
.t-state{ font-size:13px; font-weight:700; }
.t-oee  { font-size:9.5px; font-family:var(--mono); }
.t-line { font-size:12px; font-weight:600; letter-spacing:.02em; }
.t-hall { font-size:9px; letter-spacing:.14em; text-transform:uppercase; }

.legend { display:flex; flex-wrap:wrap; gap:14px; align-items:center;
          padding:0 2px; font-size:11px; color:var(--fg-dim); flex:0 0 auto; }
.legend i { display:inline-block; width:10px; height:10px; border-radius:2px;
            margin-right:5px; vertical-align:-1px; }
.legend .hint { margin-left:auto; }
.empty { color:var(--fg-dim); font-size:13px; padding:20px; }

options.onInit:
var root = htmlNode.querySelector('.board');
if (!root) { return; }
// The panel plugin hands us Grafana's *v1* theme object (config.theme), not
// GrafanaTheme2 - so these are v1 paths (typography.fontFamily.sansSerif,
// spacing.md, border.radius.sm, palette.*). Verified by dumping the object
// from inside the panel; v2 paths silently fall back and the board then stays
// dark in the light theme.
function t(path, fallback) {
  try {
    var v = path.split('.').reduce(function (o, k) { return o[k]; }, theme);
    return (v === undefined || v === null || v === '') ? fallback : v;
  } catch (e) { return fallback; }
}
var vars = {
  '--bg':       t('colors.dashboardBg', '#111217'),
  '--panel':    t('colors.panelBg', '#181b1f'),
  '--border':   t('colors.border1', 'rgba(204,204,220,0.12)'),
  '--fg':       t('colors.text', 'rgba(204,204,220,1)'),
  '--fg-dim':   t('colors.textWeak', 'rgba(204,204,220,0.65)'),
  '--fg-faint': t('colors.border2', 'rgba(204,204,220,0.30)'),
  '--green':    t('palette.greenBase', '#299c46'),
  '--yellow':   t('palette.yellow', '#ecbb13'),
  '--orange':   t('palette.orange', '#eb7b18'),
  '--red':      t('palette.redBase', '#e02f44'),
  '--font':     t('typography.fontFamily.sansSerif', 'Inter, Helvetica, Arial, sans-serif'),
  '--mono':     t('typography.fontFamily.monospace', 'monospace'),
  '--radius':   t('border.radius.sm', '2px'),
  '--sp1':      t('spacing.sm', '8px'),
  '--sp2':      t('spacing.md', '16px')
};
// a low-alpha wash for the fault card, derived from the theme's own red
function alpha(col, a) {
  var m = /^#([0-9a-f]{6})$/i.exec(String(col).trim());
  if (m) { var n = parseInt(m[1], 16);
    return 'rgba(' + ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255) + ',' + a + ')'; }
  m = /^rgba?\(([^)]+)\)$/i.exec(String(col).trim());
  if (m) { var p = m[1].split(',');
    return 'rgba(' + p[0] + ',' + p[1] + ',' + p[2] + ',' + a + ')'; }
  return col;
}
vars['--wash-stop'] = alpha(vars['--red'], 0.13);
Object.keys(vars).forEach(function (k) { root.style.setProperty(k, vars[k]); });
htmlNode._vars = vars;

// --- the detail modal ------------------------------------------------------
// It lives on document.body, not in the panel: the panel's content sits in a
// shadow root inside a Grafana grid item, and that grid item carries a CSS
// transform, which makes position:fixed resolve against the panel instead of
// the viewport. A modal built inside the panel is therefore trapped in it.
var MID = 'umh-andon-modal', SID = 'umh-andon-modal-style';
var modal = document.getElementById(MID);
if (!modal) {
  modal = document.createElement('div');
  modal.id = MID;
  document.body.appendChild(modal);
}
modal.style.display = 'none';
// the modal is outside the board, so it cannot inherit the board's variables
Object.keys(vars).forEach(function (k) { modal.style.setProperty(k, vars[k]); });

if (!document.getElementById(SID)) {
  var st = document.createElement('style');
  st.id = SID;                     // id-guarded, so a panel remount adds one copy
  st.textContent = [
    '#' + MID + ' { position:fixed; inset:0; z-index:1061; display:flex;',
    '  align-items:center; justify-content:center; font-family:var(--font); }',
    '#' + MID + ' .bd { position:absolute; inset:0; background:rgba(0,0,0,0.55); }',
    '#' + MID + ' .mw { position:relative; width:min(540px, calc(100vw - 32px));',
    '  max-height:calc(100vh - 64px); overflow:auto; background:var(--panel);',
    '  color:var(--fg); border:1px solid var(--border); border-radius:var(--radius);',
    '  box-shadow:0 8px 32px rgba(0,0,0,0.45); padding:18px 20px 16px; }',
    '#' + MID + ' .hd { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; }',
    '#' + MID + ' .eb { font-size:11px; letter-spacing:.07em; text-transform:uppercase;',
    '  color:var(--fg-dim); }',
    '#' + MID + ' .ti { font-size:19px; font-weight:600; margin-top:2px; }',
    '#' + MID + ' .cl { background:none; border:1px solid var(--border); color:var(--fg-dim);',
    '  border-radius:var(--radius); width:28px; height:28px; font-size:16px; cursor:pointer;',
    '  line-height:1; flex:0 0 auto; }',
    '#' + MID + ' .cl:hover { color:var(--fg); }',
    '#' + MID + ' .stt { display:flex; align-items:center; gap:9px; margin:14px 0 4px;',
    '  font-size:25px; font-weight:700; }',
    '#' + MID + ' .dot { width:11px; height:11px; border-radius:50%; flex:0 0 11px; }',
    '#' + MID + ' .sec { font-size:11px; letter-spacing:.07em; text-transform:uppercase;',
    '  color:var(--fg-dim); margin:18px 0 6px; }',
    '#' + MID + ' .tl { display:flex; height:22px; gap:1px; border-radius:2px; overflow:hidden; }',
    '#' + MID + ' .tl > span { min-width:2px; }',
    '#' + MID + ' .lg { display:flex; flex-wrap:wrap; gap:10px; margin-top:7px; font-size:11px;',
    '  color:var(--fg-dim); }',
    '#' + MID + ' .lg i { display:inline-block; width:9px; height:9px; border-radius:2px;',
    '  margin-right:4px; }',
    '#' + MID + ' .tiles { display:grid; grid-template-columns:repeat(3, minmax(0,1fr)); gap:9px; }',
    '#' + MID + ' .tile { border:1px solid var(--border); border-radius:var(--radius); padding:7px 9px; }',
    '#' + MID + ' .tk { font-size:10px; letter-spacing:.05em; text-transform:uppercase;',
    '  color:var(--fg-dim); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }',
    '#' + MID + ' .tv { font-size:16px; font-weight:600; font-family:var(--mono);',
    '  font-variant-numeric:tabular-nums; margin-top:2px; }',
    '#' + MID + ' .tu { font-size:11px; font-weight:400; color:var(--fg-dim); margin-left:3px; }',
    '#' + MID + ' .ft { display:flex; gap:9px; margin-top:18px; flex-wrap:wrap; }',
    '#' + MID + ' .btn { flex:1 1 auto; text-align:center; padding:9px 14px; cursor:pointer;',
    '  border:1px solid var(--border); border-radius:var(--radius); background:none;',
    '  color:var(--fg); font-size:13px; font-family:inherit; }',
    '#' + MID + ' .btn:hover { border-color:var(--fg-dim); }',
    '#' + MID + ' .note { font-size:12px; color:var(--fg-dim); margin-top:16px; }'
  ].join('\n');
  document.head.appendChild(st);
}

function tone2col(tone) {
  return tone === 'ok' ? vars['--green'] : tone === 'warn' ? vars['--yellow']
       : tone === 'heat' ? vars['--orange'] : tone === 'stop' ? vars['--red']
       : vars['--fg-faint'];
}
function esc2(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/[&<>"]/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
}
function fmt(v, unit) {
  if (v === null || v === undefined) { return '—'; }
  var dec = (unit === 'mm') ? 3 : (unit === '' ? 0 : 1);
  return Number(v).toFixed(dec);
}
// Keep whatever window and org the board is on, and survive a sub-path install
// (/grafana/d/...) by deriving the prefix from the current path.
function dashUrl(uid, slug, path) {
  var pn = window.location.pathname, i = pn.indexOf('/d/');
  var out = [];
  try {
    var q = new URLSearchParams(window.location.search);
    ['orgId', 'from', 'to', 'timezone'].forEach(function (k) {
      if (q.get(k)) { out.push(k + '=' + encodeURIComponent(q.get(k))); }
    });
  } catch (e) { /* no URLSearchParams: fall back to defaults */ }
  out.push('var-machine=' + encodeURIComponent(path));
  return (i > 0 ? pn.slice(0, i) : '') + '/d/' + uid + '/' + slug + '?' + out.join('&');
}

function closeModal() { modal.style.display = 'none'; modal.innerHTML = ''; }

function openModal(path) {
  var det = htmlNode._detail;
  if (!det || !det.info[path]) { return; }
  var s = det.info[path], STATES = htmlNode._states || {};
  var hist = det.hist[path] || [], vals = det.vals[path] || [];

  // Merge by *tone*, not by state name. An oven runs charging / heating /
  // soaking / quenching / discharging, and all five are producing, so naming
  // them in the legend gives five identical green swatches -- one colour
  // standing for five things. The exact phase stays in the segment's tooltip.
  var TONE_NAME = { ok: 'producing', warn: 'setup', heat: 'tool change',
                    stop: 'fault', idle: 'not running' };
  var segs = [];
  hist.forEach(function (h) {
    var st = STATES[h.code] || [String(h.code), 'idle'];
    var last = segs[segs.length - 1];
    if (last && last.tone === st[1]) {
      last.n += 1;
      if (last.names.indexOf(st[0]) < 0) { last.names.push(st[0]); }
    } else {
      segs.push({ tone: st[1], n: 1, names: [st[0]] });
    }
  });
  var bar = segs.length
    ? segs.map(function (g) {
        return '<span style="flex:' + g.n + ' 1 0;background:' + tone2col(g.tone)
             + '" title="' + esc2(g.names.join(', ')) + '"></span>'; }).join('')
    : '';
  var seen = {}, legend = [];
  segs.forEach(function (g) {
    var nm = TONE_NAME[g.tone] || g.tone;
    if (seen[nm]) { return; }
    seen[nm] = 1;
    legend.push('<span><i style="background:' + tone2col(g.tone) + '"></i>'
                + esc2(nm) + '</span>'); });

  var tiles = vals.map(function (v) {
    return '<div class="tile"><div class="tk">' + esc2(v.label) + '</div>'
         + '<div class="tv">' + fmt(v.value, v.unit)
         + (v.unit ? '<span class="tu">' + esc2(v.unit) + '</span>' : '')
         + '</div></div>'; }).join('');

  var foot = (s.kind === 'cnc')
    ? '<button class="btn" data-go="cnc-detail">Drill-down</button>'
      + '<button class="btn" data-go="cnc-spc">SPC</button>'
    : '<div class="note">No detail dashboard for this machine type yet '
      + '— only the CNCs have one.</div>';

  modal.innerHTML =
      '<div class="bd"></div><div class="mw" role="dialog" aria-modal="true">'
    + '<div class="hd"><div><div class="eb">' + esc2(s.line.replace('_', ' ')) + ' · '
    + esc2(s.station) + '</div><div class="ti">' + esc2(s.machine) + '</div></div>'
    + '<button class="cl" aria-label="Close">&times;</button></div>'
    + '<div class="stt" style="color:' + tone2col(s.tone) + '">'
    + '<span class="dot" style="background:' + tone2col(s.tone) + '"></span>'
    + esc2(s.label) + '</div>'
    + '<div class="sec">state over the dashboard window</div>'
    + (bar ? '<div class="tl">' + bar + '</div><div class="lg">' + legend.join('') + '</div>'
           : '<div class="note">No state history in this window.</div>')
    + (tiles ? '<div class="sec">latest values</div><div class="tiles">' + tiles + '</div>' : '')
    + '<div class="ft">' + foot + '</div></div>';
  modal.style.display = 'flex';

  modal.querySelector('.bd').addEventListener('click', closeModal);
  modal.querySelector('.cl').addEventListener('click', closeModal);
  Array.prototype.forEach.call(modal.querySelectorAll('[data-go]'), function (b) {
    b.addEventListener('click', function () {
      var uid = b.getAttribute('data-go');
      var slug = uid === 'cnc-detail' ? 'cnc-drill-down' : 'cnc-spc';
      window.location.assign(dashUrl(uid, slug, path));
    });
  });
}
htmlNode._openModal = openModal;

// One delegated listener on the board, which survives every onRender because
// only its innerHTML is replaced.
if (!root._umhClick) {
  root._umhClick = true;
  root.addEventListener('click', function (ev) {
    var card = ev.target && ev.target.closest ? ev.target.closest('.station') : null;
    if (!card) { return; }
    var path = card.getAttribute('data-path');
    if (path && htmlNode._openModal) { htmlNode._openModal(path); }
  });
}
if (!document._umhAndonEsc) {
  document._umhAndonEsc = true;
  document.addEventListener('keydown', function (ev) {
    if (ev.key !== 'Escape') { return; }
    var m = document.getElementById(MID);
    if (m && m.style.display !== 'none') { m.style.display = 'none'; m.innerHTML = ''; }
  });
}

options.onRender:
var STATES = {
  0:['idle','idle'], 10:['running','ok'], 20:['setup','warn'], 30:['FAULT','stop'],
  40:['stopped','idle'], 50:['charging','ok'], 51:['heating','ok'], 52:['soaking','ok'],
  53:['quenching','ok'], 54:['discharging','ok'], 60:['filling','ok'], 61:['washing','ok'],
  62:['rinsing','ok'], 63:['drying','ok'], 64:['draining','ok'], 70:['tool change','heat']
};
var root = htmlNode.querySelector('.board');
if (!root) { return; }
var vars = htmlNode._vars || {};

function fields(series) {
  var f = {};
  (series.fields || []).forEach(function (fl) {
    f[fl.name] = fl.values.toArray ? fl.values.toArray() : fl.values; });
  return f;
}
function pick(name) {
  var ss = (data && data.series) || [];
  for (var i = 0; i < ss.length; i++) {
    var names = (ss[i].fields || []).map(function (fl) { return fl.name; });
    if (names.indexOf(name) >= 0) { return fields(ss[i]); }
  }
  return null;
}
var f = pick('availability');
if (!f) { root.innerHTML = '<div class="empty">No data for this time range.</div>'; return; }
var histF = pick('bucket'), detF = pick('label');
var n = (f.line || []).length;
if (!n) { root.innerHTML = '<div class="empty">No assets in this time range.</div>'; return; }

var lines = {}, order = [], info = {};
for (var i = 0; i < n; i++) {
  var ln = f.line[i], code = f.state[i], s = STATES[code] || [String(code), 'idle'];
  var a = f.availability[i], q = f.quality[i];
  var oee = (a === null || a === undefined || q === null || q === undefined) ? null : a * q;
  var rec = { step: f.ord[i], station: f.station[i], machine: f.machine[i],
              label: s[0], tone: s[1], avail: a, qual: q, oee: oee,
              path: f.path[i], line: ln, kind: f.kind ? f.kind[i] : '' };
  if (!lines[ln]) { lines[ln] = []; order.push(ln); }
  lines[ln].push(rec);
  info[f.path[i]] = rec;
}
order.forEach(function (ln) { lines[ln].sort(function (a, b) { return a.step - b.step; }); });

var hist = {}, valsByPath = {};
if (histF && histF.path) {
  for (var h = 0; h < histF.path.length; h++) {
    var hp = histF.path[h];
    (hist[hp] = hist[hp] || []).push({ ts: histF.bucket[h], code: histF.state[h] });
  }
}
if (detF && detF.path) {
  for (var v = 0; v < detF.path.length; v++) {
    var vp = detF.path[v];
    (valsByPath[vp] = valsByPath[vp] || []).push({
      label: detF.label[v], unit: detF.unit[v], value: detF.value[v] });
  }
}
htmlNode._states = STATES;
htmlNode._detail = { info: info, hist: hist, vals: valsByPath };

function esc(s) { return String(s === null || s === undefined ? '' : s)
  .replace(/[&<>"]/g, function (c) {
    return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c]; }); }
function pct(x) { return (x === null || x === undefined) ? '—' : (x * 100).toFixed(0) + '%'; }
function clip(s, max) {
  s = String(s === null || s === undefined ? '' : s);
  return s.length > max ? s.slice(0, max - 1) + '\u2026' : s;
}
function col(tone) {
  return tone === 'ok' ? vars['--green'] : tone === 'warn' ? vars['--yellow']
       : tone === 'heat' ? vars['--orange'] : tone === 'stop' ? vars['--red']
       : vars['--fg-dim'];
}

// --- the drawing ----------------------------------------------------------
// A plan view of the hall: material enters on the left, three lines run left to
// right through mill -> wash -> harden, finished parts leave on the right.
var MW = 190, MH = 104, GAP = 74;          // machine box and the gap for a conveyor
var BAY = 74;                              // goods-in / goods-out bays
var PADX = 16, PADY = 14, LANE_GAP = 26;
var maxSt = 0;
order.forEach(function (ln) { maxSt = Math.max(maxSt, lines[ln].length); });
var laneH = MH + 30;                                        // room for the line label
var W = PADX * 2 + BAY * 2 + 34 + maxSt * MW + (maxSt - 1) * GAP + GAP;
var H = PADY * 2 + order.length * laneH + (order.length - 1) * LANE_GAP + 18;

function machine(kind, tone) {
  // A schematic of the real thing, so the plan reads as a shopfloor and not as
  // a row of identical boxes. Local coords inside a 62 x 74 slot.
  var c = col(tone), dim = vars['--fg-dim'], faint = vars['--fg-faint'];
  if (kind === 'cnc') {
    return '<g stroke="' + c + '" stroke-width="1.4" fill="none">'
         + '<rect x="4" y="16" width="54" height="52" rx="2" opacity="0.85"/>'
         + '<rect x="9" y="24" width="9" height="30" fill="' + c + '" opacity="0.35"/>'
         + '<rect x="18" y="28" width="20" height="11" fill="' + c + '" opacity="0.5"/>'
         + '<line x1="28" y1="39" x2="28" y2="50"/>'
         + '<rect x="16" y="54" width="34" height="6" fill="' + c + '" opacity="0.3"/>'
         + '<rect x="24" y="49" width="12" height="5" fill="' + c + '" opacity="0.6"/>'
         + '<line x1="4" y1="68" x2="58" y2="68" stroke="' + faint + '"/>'
         + '</g>';
  }
  if (kind === 'washing') {
    return '<g stroke="' + c + '" stroke-width="1.4" fill="none">'
         + '<rect x="4" y="22" width="54" height="46" rx="3" opacity="0.85"/>'
         + '<circle cx="31" cy="47" r="12" opacity="0.9"/>'
         + '<circle cx="31" cy="47" r="5" fill="' + c + '" opacity="0.4" stroke="none"/>'
         + '<path d="M8 33 q6 -4 12 0 t12 0 t12 0" stroke="' + dim + '" stroke-width="1"/>'
         + '<line x1="14" y1="16" x2="14" y2="22"/><line x1="31" y1="14" x2="31" y2="22"/>'
         + '<line x1="48" y1="16" x2="48" y2="22"/>'
         + '<line x1="14" y1="68" x2="48" y2="68" stroke="' + faint + '"/>'
         + '</g>';
  }
  return '<g stroke="' + c + '" stroke-width="1.4" fill="none">'
       + '<rect x="4" y="20" width="54" height="48" rx="2" opacity="0.85"/>'
       + '<line x1="42" y1="22" x2="42" y2="66"/>'
       + '<line x1="38" y1="40" x2="38" y2="48" stroke-width="2"/>'
       + '<path d="M10 60 l5 -7 l5 7 l5 -7 l5 7 l5 -7" stroke="' + c + '" opacity="0.8"/>'
       + '<path d="M10 46 l5 -7 l5 7 l5 -7 l5 7 l5 -7" stroke="' + c + '" opacity="0.45"/>'
       + '<rect x="10" y="26" width="24" height="7" fill="' + c + '" opacity="0.3"'
       + ' stroke="none"/>'
       + '<rect x="46" y="12" width="8" height="8" fill="' + c + '" opacity="0.35"'
       + ' stroke="none"/>'
       + '</g>';
}

function conveyor(x, y, w, flowing, label) {
  var c = flowing ? vars['--green'] : vars['--red'];
  var g = '<g>';
  if (flowing) {
    g += '<line x1="' + x + '" y1="' + (y - 4) + '" x2="' + (x + w) + '" y2="' + (y - 4)
       + '" stroke="' + c + '" stroke-width="1.4"/>'
       + '<line x1="' + x + '" y1="' + (y + 4) + '" x2="' + (x + w) + '" y2="' + (y + 4)
       + '" stroke="' + c + '" stroke-width="1.4"/>';
    for (var r = x + 8; r < x + w - 4; r += 12) {
      g += '<circle cx="' + r + '" cy="' + y + '" r="1.6" fill="' + c + '" opacity="0.6"/>';
    }
  } else {
    g += '<line x1="' + x + '" y1="' + (y - 4) + '" x2="' + (x + w) + '" y2="' + (y - 4)
       + '" stroke="' + c + '" stroke-width="1.4" stroke-dasharray="4 4"/>'
       + '<line x1="' + x + '" y1="' + (y + 4) + '" x2="' + (x + w) + '" y2="' + (y + 4)
       + '" stroke="' + c + '" stroke-width="1.4" stroke-dasharray="4 4"/>'
       + (label === false || w < 56 ? ''
          : '<text class="t-hall" x="' + (x + w / 2) + '" y="' + (y + 18) + '" fill="' + c
            + '" text-anchor="middle">no flow</text>');
  }
  return g + '</g>';
}

var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="xMidYMid meet">';
// hall shell
svg += '<rect x="3" y="3" width="' + (W - 6) + '" height="' + (H - 6)
     + '" rx="3" fill="none" stroke="' + vars['--fg-faint'] + '" stroke-width="2"/>';
// the two bays
var bayIn = PADX, bayOut = W - PADX - BAY;
[['goods in', bayIn], ['goods out', bayOut]].forEach(function (b) {
  svg += '<rect x="' + b[1] + '" y="' + PADY + '" width="' + BAY + '" height="'
       + (H - 2 * PADY) + '" rx="2" fill="' + vars['--panel'] + '" stroke="'
       + vars['--border'] + '" stroke-dasharray="3 3"/>'
       + '<text class="t-hall" transform="translate(' + (b[1] + BAY / 2) + ','
       + (H / 2) + ') rotate(-90)" fill="' + vars['--fg-dim']
       + '" text-anchor="middle">' + b[0] + '</text>';
  for (var pz = 0; pz < 3; pz++) {
    var py = PADY + 26 + pz * 46;
    svg += '<g stroke="' + vars['--fg-faint'] + '" fill="none" stroke-width="1">'
         + '<rect x="' + (b[1] + 14) + '" y="' + py + '" width="' + (BAY - 28)
         + '" height="26" rx="1"/>'
         + '<line x1="' + (b[1] + 14) + '" y1="' + (py + 13) + '" x2="'
         + (b[1] + BAY - 14) + '" y2="' + (py + 13) + '"/></g>';
  }
});

var x0 = bayIn + BAY + 34;
order.forEach(function (ln, li) {
  var sts = lines[ln];
  var top = PADY + li * (laneH + LANE_GAP);
  var mid = top + 18 + MH / 2;
  svg += '<text class="t-line" x="' + x0 + '" y="' + (top + 12) + '" fill="'
       + vars['--fg'] + '">' + esc(ln.replace('_', ' ')) + '</text>';
  // material path from the bay into the first machine and out of the last
  svg += conveyor(bayIn + BAY + 4, mid, 26, sts[0].tone === 'ok', false);
  sts.forEach(function (s, k) {
    var mx = x0 + k * (MW + GAP), my = top + 18;
    svg += '<g class="station" data-path="' + esc(s.path) + '">'
         + '<title>' + esc(s.station) + ' · ' + esc(s.machine) + ' — ' + esc(s.label)
         + ' (click for details)</title>'
         + '<rect class="hit" x="' + mx + '" y="' + my + '" width="' + MW + '" height="' + MH
         + '" rx="3" fill="' + vars['--panel'] + '" stroke="' + vars['--border'] + '"/>'
         + '<rect x="' + mx + '" y="' + my + '" width="4" height="' + MH + '" rx="2" fill="'
         + col(s.tone) + '"/>'
         + '<g class="body" transform="translate(' + (mx + 12) + ',' + (my + 12) + ')">'
         + machine(s.kind, s.tone) + '</g>'
         + '<text class="t-st" x="' + (mx + 82) + '" y="' + (my + 20) + '" fill="'
         + vars['--fg-dim'] + '">' + esc(s.station) + '</text>'
         + '<text class="t-state" x="' + (mx + 82) + '" y="' + (my + 42) + '" fill="'
         + col(s.tone) + '">' + esc(s.label) + '</text>'
         + '<text class="t-mach" x="' + (mx + 82) + '" y="' + (my + 58) + '" fill="'
         + vars['--fg-dim'] + '">' + esc(clip(s.machine, 20)) + '</text>'
         + '<text class="t-oee" x="' + (mx + 82) + '" y="' + (my + 78) + '" fill="'
         + vars['--fg-dim'] + '">OEE ' + pct(s.oee) + '</text>'
         + '<circle cx="' + (mx + MW - 12) + '" cy="' + (my + 12) + '" r="4.5" fill="'
         + col(s.tone) + '"/>'
         + '</g>';
    if (k < sts.length - 1) {
      svg += conveyor(mx + MW + 6, mid, GAP - 12, s.tone === 'ok');
    } else {
      svg += conveyor(mx + MW + 6, mid, bayOut - (mx + MW) - 10, s.tone === 'ok', false);
    }
  });
});
svg += '</svg>';

var TONES = [['ok', 'producing'], ['warn', 'setup'], ['heat', 'tool change'],
             ['stop', 'fault'], ['idle', 'not running']];
var legend = TONES.map(function (t) {
  return '<span><i style="background:' + col(t[0]) + '"></i>' + t[1] + '</span>'; }).join('');

root.innerHTML = '<div class="plan">' + svg + '</div>'
               + '<div class="legend">' + legend
               + '<span class="hint">click a machine for details</span></div>';
